from itertools import product

def can_release(reviewed, approved):
    return reviewed and approved

def must_hold(reviewed, approved):
    return (not reviewed) or (not approved)

for reviewed, approved in product((False, True), repeat=2):
    assert must_hold(reviewed, approved) == (not can_release(reviewed, approved))
assert can_release(True, True) is True
assert must_hold(True, False) is True
print('four release cases checked')
